contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 n, address a1, address a2) public {
        require(n >= 1);
        require(a1 != address(0) && a2 != address(0));

        // make this test contract act as lrtConfig, granting all roles via fallback
        c.initialize(address(this));
        c.updateMaxNodeDelegatorCount(n);
        assert(c.maxNodeDelegatorCount() == n);

        address[] memory arr = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            arr[i] = a1;
        }
        c.addNodeDelegatorContractToQueue(arr);

        bool reverted;
        address[] memory extra = new address[](1);
        extra[0] = a2;
        try c.addNodeDelegatorContractToQueue(extra) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            c.getNodeDelegatorQueue().length == n &&
            c.maxNodeDelegatorCount() == n
        );
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        if (msg.sig == bytes4(keccak256("hasRole(bytes32,address)"))) {
            return abi.encode(true);
        }
        return "";
    }

    receive() external payable {}
}

